/***
 * MARK: agentLogStreamer
 * @description A pure, harness-agnostic log streamer for agent stages. It
 *   consumes the engine's NORMALIZED agent-event vocabulary
 *   (`api/agent/sessionEvents.js`) and produces grouped, structured log
 *   entries — one entry per semantic block (assistant text block, thinking
 *   block, tool call, tool result, error, system line) instead of one fragment
 *   per streamed token.
 *
 *   The event→record conversion lives in the unified log processor
 *   (`./logProcessor.js`) — this module is a thin state machine shell that
 *   owns feed plumbing (`consumeFeed`/`snapshot`/`renderText`/`renderFeed`)
 *   and delegates every event to the processor. See the processor for the
 *   normalized event contract and grouping semantics.
 *
 *   # Feeds
 *
 *   Entries are placed on one or more dedicated feeds (`main`, `thinking`,
 *   `tools`, plus the unified lanes `telemetry` and `raw`) so each consumer
 *   can pull its own stream: the main feed is the narrative (assistant text,
 *   tool call lines, errors, system lines, permission/plan lines), the
 *   thinking feed carries full thinking blocks, the tools feed carries tool
 *   calls with full args plus tool output, the telemetry feed carries usage
 *   records, and the raw feed carries bounded unmapped wire evidence.
 *   `consumeFeed` hands each entry to exactly one consumer per feed;
 *   `snapshot` gives the full structured view.
 *
 *   # Rendering (backwards compatibility)
 *
 *   `renderText()` renders the legacy tag grammar (`[AGENT]`, `[TOOL]`,
 *   `[RESULT]`, `[ERROR]`, `[THINKING]`, `[INFO]`) as complete lines/blocks —
 *   a pure derived view over the structured entries via the shared renderer
 *   (`renderLogEntriesText` in `api/watch/processLogs.js`); nothing is stored
 *   as text. The existing line-based tag filters and severity coloring keep
 *   working against the rendered view. Thinking is collapsed to a
 *   `[THINKING] (N chars)` marker on the main feed
 *   by default (`hideThinking: false` opts into full thinking text there).
 *
 * @example
 *   const streamer = createAgentLogStreamer({ hideThinking: true });
 *   const appended = streamer.handleEvent({ type: "assistant_delta", assistantMessageEvent: { type: "text_delta", delta: "Hello" } });
 *   // appended === [] (buffering; no token fragments leak out)
 *   streamer.handleEvent({ type: "assistant_delta", assistantMessageEvent: { type: "text_end" } });
 *   // next call returns [{ kind: "assistant", feed: "main", text: "Hello", ... }]
 ***/
import { renderLogEntriesText } from "../../watch/processLogs.js";
import {
	createLogProcessor,
	DEFAULT_PROCESSOR_OPTIONS,
} from "./logProcessor.js";

/***
 * MARK: DEFAULT_STREAMER_OPTIONS
 * @description Default options for `createAgentLogStreamer`. `maxEntryBytes`
 *   is 0 (uncapped) so the streamer never truncates narrative text; task-log
 *   growth is bounded by the structured-entry cap (`config.logEntriesMaxCount`)
 *   rather than a byte cap. Consumers that need a hard per-entry bound (e.g.
 *   live push payloads) can set it explicitly. Lane budgets
 *   (`telemetryMaxCount`, `rawMaxCount`, `rawMaxBytes`) bound the unified
 *   telemetry/raw lanes inside the total cap.
 ***/
export const DEFAULT_STREAMER_OPTIONS = Object.freeze({
	feeds: Object.freeze(["main", "thinking", "tools", "telemetry", "raw"]),
	hideThinking: DEFAULT_PROCESSOR_OPTIONS.hideThinking,
	toolArgsMaxLength: DEFAULT_PROCESSOR_OPTIONS.toolArgsMaxLength,
	resultMaxLength: DEFAULT_PROCESSOR_OPTIONS.resultMaxLength,
	maxEntryBytes: DEFAULT_PROCESSOR_OPTIONS.maxEntryBytes,
	maxEntries: DEFAULT_PROCESSOR_OPTIONS.maxEntries,
	telemetryMaxCount: DEFAULT_PROCESSOR_OPTIONS.telemetryMaxCount,
	rawMaxCount: DEFAULT_PROCESSOR_OPTIONS.rawMaxCount,
	rawMaxBytes: DEFAULT_PROCESSOR_OPTIONS.rawMaxBytes,
	harnessId: DEFAULT_PROCESSOR_OPTIONS.harnessId,
	model: DEFAULT_PROCESSOR_OPTIONS.model,
	runId: DEFAULT_PROCESSOR_OPTIONS.runId,
});

const KNOWN_FEEDS = new Set(["main", "thinking", "tools", "telemetry", "raw"]);

/***
 * MARK: createAgentLogStreamer
 * @description Creates a grouped log streamer for one agent stage run. The
 *   streamer is pure: no harness imports, no I/O — it only transforms the
 *   normalized agent-event vocabulary into structured entries and rendered
 *   text views (via the unified log processor).
 * @example
 *   const streamer = createAgentLogStreamer({ hideThinking: true });
 *   streamer.handleEvent({ type: "run_started" });
 *   streamer.system("[AGENT] Working on git branch 'kb/1'");
 *   const entries = streamer.snapshot().entries;
 * @param {Object} [options]
 * @param {string[]} [options.feeds] - Dedicated feeds to maintain (default main/thinking/tools/telemetry/raw).
 * @param {boolean} [options.hideThinking] - Collapse thinking on the main feed to a sized marker (default true).
 * @param {number} [options.toolArgsMaxLength] - Max chars of rendered args on the [TOOL] line (default 400).
 * @param {number} [options.resultMaxLength] - Max chars of a [RESULT] excerpt (default 600).
 * @param {number} [options.maxEntryBytes] - Hard cap per entry text; 0 disables (default 0).
 * @param {number} [options.maxEntries] - Total entries retained; older ones are evicted under a marker (default 500).
 * @param {number} [options.telemetryMaxCount] - Telemetry records retained (default 100).
 * @param {number} [options.rawMaxCount] - Raw evidence records retained (default 50).
 * @param {number} [options.rawMaxBytes] - Per-record raw source cap (default 8192).
 * @param {string} [options.harnessId] - Harness identity stamped on records.
 * @param {string} [options.model] - Model ref stamped on records.
 * @param {string} [options.runId] - Run/conversation id stamped on records.
 * @returns {Object} Streamer with handleEvent/system/consumeFeed/snapshot/renderText/renderFeed.
 ***/
export function createAgentLogStreamer(options = {}) {
	const merged = { ...DEFAULT_STREAMER_OPTIONS, ...options };
	const feeds = (
		Array.isArray(merged.feeds) ? merged.feeds : DEFAULT_STREAMER_OPTIONS.feeds
	).filter((f) => KNOWN_FEEDS.has(f));
	const processor = createLogProcessor(merged);

	/** Per-feed consumption bookmarks: each feed's entries are delivered once. */
	const consumedByFeed = new Map(feeds.map((f) => [f, new Set()]));
	const entries = processor.entries;

	/***
	 * MARK: streamer.handleEvent
	 * @description Consumes one normalized agent event and returns the entries
	 *   appended by it (in order). Token deltas buffer internally and only
	 *   surface when their block completes. Unknown wire events are captured
	 *   into the bounded raw lane (never silently dropped).
	 * @example streamer.handleEvent({ type: "run_started" }) => []
	 * @param {Object|null} event - A normalized agent event (sessionEvents.js vocabulary).
	 * @returns {Array<Object>} The entries appended now.
	 ***/
	function handleEvent(event) {
		return processor.handleEvent(event);
	}

	/***
	 * MARK: streamer.system
	 * @description Appends a system/status line (runner-emitted [AGENT]/[WARN]
	 *   messages) to the main feed so it appears in the structured entries too.
	 * @example streamer.system("[AGENT] Agent reasoning with model deepseek…")
	 * @param {string} text
	 * @param {string} [kind] - Entry kind, defaults to "system".
	 * @returns {Object} The appended entry.
	 ***/
	function system(text, kind = "system") {
		return processor.system(text, kind);
	}

	/***
	 * MARK: streamer.consumeFeed
	 * @description Pull-based dedicated feed: returns the entries placed on
	 *   `feed` that this feed's consumer has not received yet, handing each
	 *   entry to exactly one consumer per feed. A second consume returns empty
	 *   until new entries arrive.
	 * @example streamer.consumeFeed("thinking") => [thinkingEntry]
	 * @param {string} feed - One of the configured feeds (main/thinking/tools/telemetry/raw).
	 * @returns {Array<Object>} The newly available entries for that feed.
	 ***/
	function consumeFeed(feed) {
		if (!consumedByFeed.has(feed)) {
			throw new Error(
				`Unknown log feed '${feed}' (configured: ${feeds.join(", ")})`,
			);
		}
		const consumed = consumedByFeed.get(feed);
		const delivered = entries.filter(
			(e) => e.feeds.includes(feed) && !consumed.has(e.id),
		);
		for (const entry of delivered) consumed.add(entry.id);
		return delivered;
	}

	/***
	 * MARK: streamer.snapshot
	 * @description Structured snapshot of everything logged so far: the flat
	 *   entry list plus each configured feed's placed entries.
	 * @example streamer.snapshot() => { entries: [...], feeds: { main: [...], thinking: [...], tools: [...] } }
	 * @returns {{entries: Array<Object>, feeds: Object<string, Array<Object>>}}
	 ***/
	function snapshot() {
		const feedsSnapshot = Object.fromEntries(
			feeds.map((feed) => [feed, entries.filter((e) => e.feeds.includes(feed))]),
		);
		return { entries: [...entries], feeds: feedsSnapshot };
	}

	/***
	 * MARK: streamer.renderText
	 * @description Renders the combined log text as a pure derived view over
	 *   the structured entries (via the shared `renderLogEntriesText`):
	 *   every main/tools entry in order, thinking collapsed to its marker.
	 *   Telemetry and raw lanes never leak into the narrative view. Legacy
	 *   tag prefixes are preserved. Nothing is stored — task log storage is
	 *   the structured entries alone.
	 * @example streamer.renderText() => "[AGENT] reasoning…\n[TOOL] bash(…)\n[RESULT] ok"
	 * @returns {string}
	 ***/
	function renderText() {
		return renderLogEntriesText(entries);
	}

	/***
	 * MARK: streamer.renderFeed
	 * @description Renders one feed's entries as text (derived view via the
	 *   shared `renderLogEntriesText`).
	 * @example streamer.renderFeed("tools") => "[TOOL] bash(…)\n[RESULT] ok"
	 * @param {string} feed
	 * @returns {string}
	 ***/
	function renderFeed(feed) {
		if (!consumedByFeed.has(feed)) {
			throw new Error(
				`Unknown log feed '${feed}' (configured: ${feeds.join(", ")})`,
			);
		}
		return renderLogEntriesText(entries, { feed });
	}

	return {
		handleEvent,
		system,
		consumeFeed,
		snapshot,
		renderText,
		renderFeed,
	};
}

// Domain: Watching the Work — task progress entries and their feeds.
import { config } from "../config.js";
import { redactDeepStrings, redactSecretsText } from "../../shared/redactSecrets.js";
/***
 * MARK: _logEntryKindFromText
 * @description Maps a rendered log chunk to its structured entry kind and
 *   feed using the shared tag grammar. Untagged text is assistant narrative.
 * @example _logEntryKindFromText('[TOOL] bash(…)') => { kind: 'tool', feed: 'tools' }
 * @param {string} text
 * @returns {{kind: string, feed: string}}
 ***/
function _logEntryKindFromText(text) {
	const raw = String(text);
	const lines = raw.split("\n");
	const firstLine = lines[0] || "";
	if (/^\[(ERROR|FAIL|STDERR)\]/i.test(firstLine))
		return { kind: "error", feed: "main" };
	const checkLine = /^\[STDOUT\]/i.test(firstLine) && lines.length > 1 ? lines[1] : firstLine;
	if (/^\[(TOOL|RESULT)\]/.test(checkLine))
		return { kind: "tool", feed: "tools" };
	if (/^\[THINKING\]/.test(checkLine))
		return { kind: "thinking", feed: "thinking" };
	if (/^\[(ERROR|FAIL|STDERR)\]/.test(checkLine))
		return { kind: "error", feed: "main" };
	if (/^\[(INFO|SYSTEM|GIT|CI\/CMD|CI|HUMAN|WARN)\]/.test(checkLine)) {
		return { kind: "system", feed: "main" };
	}
	if (/^\[AGENT\]/.test(checkLine)) return { kind: "assistant", feed: "main" };
	// Runner frames carry an inline `[runner <id>]` prefix (ingested over
	// the wire). They get their own kind so the log viewer can tag and
	// filter them per runner instead of lumping them into assistant output.
	if (/^\[runner[ \]]/i.test(checkLine)) return { kind: "runner", feed: "main" };
	// Untagged text is assistant narrative (block text from the agent streamer).
	return { kind: "assistant", feed: "main" };
}

/** Monotonic counter for synthesized log entry ids (never Date.now() so
 *  same-millisecond entries cannot collide). */
let _logEntryIdCounter = 0;

/***
 * MARK: _synthesizedLogEntry
 * @description Wraps a rendered log chunk as a structured log entry so the
 *   UI has one uniform shape for every log source (agent streamer entries
 *   and system/GIT/CI lines alike).
 * @example _synthesizedLogEntry('[GIT] Switched to main') => { kind: 'system', text: '…', … }
 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`).
 * @returns {Object} A structured log entry.
 ***/
function _synthesizedLogEntry(chunk, meta = {}) {
	_logEntryIdCounter += 1;
	const { kind, feed } = _logEntryKindFromText(chunk);
	// Only a plain bag spreads into meta: exotic inputs (strings, Dates,
	// arrays) degrade to {} instead of scattering characters into the entry.
	const cleanedMeta = redactDeepStrings(meta || {});
	const metaBag =
		cleanedMeta && typeof cleanedMeta === "object" && !Array.isArray(cleanedMeta)
			? cleanedMeta
			: {};
	return {
		id: `log-${_logEntryIdCounter}`,
		ts: new Date().toISOString(),
		feed,
		feeds: [feed],
		kind,
		turn: null,
		// Redacted at synthesis so command output, git lines, and runner
		// text frames can never store secrets or PII. Clean text passes
		// through byte-identical.
		text: redactSecretsText(String(chunk)),
		meta: { source: "process-log", ...metaBag },
	};
}

/***
 * MARK: _capLogEntries
 * @description Keeps at most `config.logEntriesMaxCount` entries on a task,
 *   dropping the oldest and recording the eviction under a single updating
 *   marker entry (mirrors the streamer's eviction behaviour).
 * @example _capLogEntries(task)
 * @param {Object} task
 * @returns {void}
 ***/
function _capLogEntries(task) {
	const max = config.logEntriesMaxCount;
	if (!Array.isArray(task.logEntries) || task.logEntries.length <= max) return;
	const existingMarker = task.logEntries[0];
	const hasMarker = existingMarker?.meta?.evictedCount !== undefined;
	// Reserve one slot for the marker so the cap holds after it is unshifted.
	const keepTarget = hasMarker ? max : max - 1;
	const overflow = task.logEntries.length - keepTarget;
	if (overflow <= 0) return;
	task.logEntries.splice(hasMarker ? 1 : 0, overflow);
	const markerText = `[INFO] (${overflow} earlier log entries evicted)`;
	if (hasMarker) {
		const previousCount = existingMarker.meta.evictedCount + overflow;
		existingMarker.text = `[INFO] (${previousCount} earlier log entries evicted)`;
		existingMarker.meta = { evictedCount: previousCount };
	} else {
		_logEntryIdCounter += 1;
		task.logEntries.unshift({
			id: `log-${_logEntryIdCounter}`,
			ts: new Date().toISOString(),
			feed: "main",
			feeds: ["main"],
			kind: "system",
			turn: null,
			text: markerText,
			meta: { evictedCount: overflow },
		});
	}
}

/***
 * MARK: parseLegacyProcessLogText
 * @description Parses legacy rendered process-log text (line-based tag
 *   grammar) into structured entries (blank lines dropped, consecutive
 *   duplicates de-duped) so tasks predating the structured-entries era still
 *   serve feeds. Shared by the markdown legacy-section synthesis
 *   (`parseTaskMarkdown`) and the in-memory feed fallback below — it is a
 *   read-only migration path, never a second storage format.
 * @example parseLegacyProcessLogText('[INFO] a\n[INFO] a') => [entry('[INFO] a')]
 * @param {string} text
 * @returns {Array<Object>} Structured log entries.
 ***/
export function parseLegacyProcessLogText(text) {
	const source = typeof text === "string" ? text : "";
	if (!source.trim()) return [];
	const parsed = [];
	for (const line of source.split("\n")) {
		if (!line.trim()) continue;
		if (parsed.length > 0 && parsed[parsed.length - 1].text === line) continue;
		parsed.push(_synthesizedLogEntry(line));
	}
	return parsed;
}

/***
 * MARK: renderLogEntriesText
 * @description The ONE shared renderer from structured log entries to legacy
 *   tag-grammar text — every text view is derived here at read time, never
 *   stored. With a `feed` option only that feed's entries render; without
 *   one, the combined main+tools narrative renders (thinking entries stay
 *   out, mirroring the streamer's combined view).
 * @example renderLogEntriesText(entries) => "[AGENT] reasoning…\n[TOOL] bash(…)"
 * @example renderLogEntriesText(entries, { feed: 'tools' }) => "[TOOL] bash(…)"
 * @param {Array<Object>} entries
 * @param {{ feed?: string }} [opts]
 * @returns {string}
 ***/
export function renderLogEntriesText(entries, { feed } = {}) {
	const selected = (Array.isArray(entries) ? entries : []).filter((entry) => {
		if (!entry) return false;
		const placed = Array.isArray(entry.feeds) ? entry.feeds : [entry.feed];
		if (feed) return placed.includes(feed);
		return placed.includes("main") || placed.includes("tools");
	});
	return selected.map((entry) => entry.text).join("\n");
}

/***
 * MARK: _logEntriesForFeed
 * @description Collects a task's entries placed on one feed (main/thinking/
 *   tools), bounded to `config.logEntriesMaxCount`. Structured entries are
 *   the single storage path; the legacy-text fallback only exists for tasks
 *   still carrying a pre-migration `processLogs` string (read-only).
 * @example _logEntriesForFeed(task, 'thinking') => [thinkingEntry, …]
 * @param {Object} task
 * @param {string} feed
 * @returns {Array<Object>} The feed's entries, oldest first.
 ***/
export function _logEntriesForFeed(task, feed) {
	const structured = Array.isArray(task?.logEntries)
		? task.logEntries.filter(Boolean)
		: [];
	const all =
		structured.length > 0
			? structured
			: parseLegacyProcessLogText(task?.processLogs);
	const matching = all.filter((entry) =>
		(Array.isArray(entry.feeds) ? entry.feeds : [entry.feed]).includes(feed),
	);
	const capped = { logEntries: matching };
	_capLogEntries(capped);
	return capped.logEntries;
}

/***
 * MARK: _appendLogEntries
 * @description Appends structured log entries to task.logEntries, capping the
 *   array to `config.logEntriesMaxCount`.
 * @example _appendLogEntries(task, streamer.snapshot().entries)
 * @param {Object} task
 * @param {Array<Object>} newEntries
 * @returns {void}
 ***/
export function _appendLogEntries(task, newEntries) {
	if (!task || !Array.isArray(newEntries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	for (const entry of newEntries) {
		if (entry) task.logEntries.push(entry);
	}
	_capLogEntries(task);
}

/***
 * MARK: _replaceLogEntries
 * @description Replaces the log entries accumulated for one stage run (the
 *   synthesized tail of the array) with the agent streamer's structured
 *   entries, upgrading turn-grouped text blocks into the task's log.
 * @example _replaceLogEntries(task, startIndex, result.logEntries)
 * @param {Object} task
 * @param {number} startIndex - Index where the stage's entries begin.
 * @param {Array<Object>} entries - The structured entries for the stage.
 * @returns {void}
 ***/
export function _replaceLogEntries(task, startIndex, entries) {
	if (!task || !Array.isArray(entries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	const safeStart = Math.max(0, Math.min(startIndex, task.logEntries.length));
	task.logEntries.splice(safeStart);
	_appendLogEntries(task, entries);
}

/***
 * MARK: _appendProcessLog
 * @description Appends a rendered log chunk to the task's structured
 *   `logEntries` as one synthesized entry — the single log storage path
 *   (agent streamer entries replace the synthesized ones when the stage
 *   result arrives). Growth is bounded by `config.logEntriesMaxCount` with
 *   an eviction marker; the historical rendered-text copy
 *   (`task.processLogs`) is gone and every text view is derived from entries
 *   at read time via `renderLogEntriesText`.
 * @example _appendProcessLog(task, '[GIT] Switched to main')
 * @param {Object} task
 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`).
 * @returns {void}
 ***/
export function _appendProcessLog(task, chunk, meta = {}) {
	if (!task || !chunk) return;
	_appendLogEntries(task, [_synthesizedLogEntry(String(chunk).trim(), meta)]);
}

import { _appendLogEntries, _appendProcessLog } from "../watch/index.js";
import { config } from "../config.js";
import { git } from "../git.js";
import { createLogProcessor } from "../agent/logStream/logProcessor.js";

/***
 * MARK: ExecutionLedger
 * @description Backend receiving side of the Runner wire protocol (ADR 0009
 *   lifecycle steps 4–6): sequenced progress events, sequenced log frames,
 *   idempotent completion, and interruption. Every mutating call first
 *   checks the ClaimStore lease — a stale epoch is rejected before any
 *   state changes, which is what makes a partitioned zombie's late report
 *   a 409 instead of a double completion (R01). Dedupe is per execution:
 *   a retried report is a recorded no-op, never a duplicate stage (step 4).
 *   Log gaps are represented in the data ("frames missing — Runner
 *   disconnected"), never papered over (R14). Completion records the
 *   Runner's report (SHA/branch/posture) and releases the lease; stage
 *   advancement stays engine-owned until the dispatch integration lands.
 *   Monitor counters back the Phase 2 "pageable-zero" reconcile/divergence
 *   signals. In-memory for Phase 2 (same durability story as ClaimStore).
 * @example const ledger = new ExecutionLedger()
 * @param {Object} [opts] - Options.
 ***/
/***
 * MARK: ExecutionLedger
 * @description In-memory receiving side for Runner progress/logs/complete/
 *   interrupt keyed by lease. See the module block for the fencing contract.
 * @example const ledger = new ExecutionLedger(); ledger.snapshot() => { progressRecorded: 0, ... }
 ***/
/***
 * MARK: MAX_RUNNER_INTERRUPTS
 * @description Bound on consecutive Runner-death interrupts for one
 *   task+stage (G7): a Runner that keeps dying mid-stage re-queues as
 *   `interrupted` each time, but past this many in a row the interrupt
 *   escalates (history entry + `interruptEscalations` monitor counter +
 *   `escalated` reply flag) so the death loop gets operator attention
 *   instead of spinning forever. A successful completion resets the count.
 * @example MAX_RUNNER_INTERRUPTS => 5
 ***/
export const MAX_RUNNER_INTERRUPTS = 5;
export { formatPosture, servingModelFor } from "./runnerPosture.js";
import { cleanReportedPosture } from "./runnerPosture.js";

/***
 * MARK: ExecutionLedger
 * @description In-memory receiving side for Runner progress/logs/complete/
 *   interrupt keyed by lease (D1 fencing, R01/R14); consecutive Runner-death
 *   interrupts escalate past MAX_RUNNER_INTERRUPTS (G7). See the module
 *   block above for the full fencing contract.
 * @example const ledger = new ExecutionLedger()
 * @example ledger.snapshot() => { progressRecorded: 0, … }
 ***/
export class ExecutionLedger {
	constructor() {
		this.seenProgress = new Set();
		this.logNextSeq = new Map();
		this.logEventNextSeq = new Map();
		this.logProcessors = new Map();
		this.lastStage = new Map();
		this.stagePrompt = new Map();
		this.stageServing = new Map();
		this.counters = {
			progressRecorded: 0,
			progressDuplicates: 0,
			logFrames: 0,
			logGaps: 0,
			logDuplicates: 0,
			logEventBatches: 0,
			logEventGaps: 0,
			logEventDuplicates: 0,
			logEventsDropped: 0,
			completions: 0,
			completionDuplicates: 0,
			staleRejected: 0,
			interrupts: 0,
			interruptEscalations: 0,
			divergences: 0,
			unverifiedSha: 0,
			verifiedSha: 0,
		};
	}

	static _stale(taskId, why) {
		const err = new Error(`Stale execution for task ${taskId}: ${why}.`);
		err.statusCode = 409;
		err.code = "STALE_EPOCH";
		return err;
	}

	_holdOrThrow(claimStore, taskId, executionId, epoch) {
		const hold = claimStore.describe(taskId);
		if (
			!hold ||
			hold.executionId !== executionId ||
			hold.epoch !== epoch
		) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "epoch or execution mismatch");
		}
		return hold;
	}

	recordProgress({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		stageId,
		event,
		prompt = null,
		harness = null,
		model = null,
	}) {
		const hold = this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (hold.runnerId !== runnerId) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "lease belongs to another Runner");
		}
		if (!stageId || !event) {
			const err = new Error("progress requires stageId and event.");
			err.statusCode = 400;
			err.code = "INVALID_PROGRESS_ARGS";
			throw err;
		}
		const key = `${executionId}|${stageId}|${event}`;
		if (this.seenProgress.has(key)) {
			this.counters.progressDuplicates += 1;
			return { recorded: true, duplicate: true };
		}
		this.seenProgress.add(key);
		this.lastStage.set(executionId, stageId);
		// Stage prompt payload (observability only): the exact prompt the
		// Runner curated for this execution, capped at ingest. Kept per
		// live execution and dropped on complete/interrupt with the rest
		// of the per-execution state.
		if (event === "prompted" && typeof prompt === "string" && prompt) {
			this.stagePrompt.set(executionId, prompt.slice(0, 20000));
		}
		// Serving harness/model (observability only): what the Runner
		// actually runs this execution on. Same lifecycle as the prompt.
		// The "default" sentinel counts as no model: Runners older than
		// the servingModelFor fix report `config.model || "default"`, and
		// the engine uses "default" to mean harness-managed (no pinned
		// model). Storing it verbatim would render the fake `default`
		// pill the fix removes, so ingest normalizes it to null and the
		// UI hides the pill until every Runner has upgraded.
		const servingModel =
			typeof model === "string" && model.trim() && model.trim().toLowerCase() !== "default"
				? model.trim()
				: null;
		if (event === "prompted" && ((typeof harness === "string" && harness.trim()) || servingModel)) {
			this.stageServing.set(executionId, {
				harness: typeof harness === "string" && harness.trim() ? harness.trim() : null,
				model: servingModel,
			});
		}
		this.counters.progressRecorded += 1;
		const task = taskStore.getTask(projectId, taskId);
		task?.history?.push({
			timestamp: new Date().toISOString(),
			action: `Runner ${runnerId} stage ${stageId}: ${event}`,
		});
		return { recorded: true, duplicate: false };
	}

	ingestLogs({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		seq,
		bytes,
	}) {
		this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (!Number.isInteger(seq) || seq < 0 || typeof bytes !== "string") {
			const err = new Error("logs requires an integer seq and string bytes.");
			err.statusCode = 400;
			err.code = "INVALID_LOG_ARGS";
			throw err;
		}
		const next = this.logNextSeq.get(executionId) ?? 0;
		if (seq < next) {
			this.counters.logDuplicates += 1;
			return { accepted: true, duplicate: true, seq };
		}
		const task = taskStore.getTask(projectId, taskId);
		if (seq > next) {
			this.counters.logGaps += 1;
			this.counters.logFrames += 1;
			_appendProcessLog(
				task,
				`[runner ${runnerId}] logs truncated — Runner disconnected (frames ${next}–${seq - 1} missing)`,
				{ runnerId },
			);
		} else {
			this.counters.logFrames += 1;
		}
		_appendProcessLog(task, `[runner ${runnerId}] ${bytes}`, {
			runnerId,
			executionId,
			seq,
		});
		this.logNextSeq.set(executionId, seq + 1);
		return { accepted: true, duplicate: false, seq };
	}

	processorFor(executionId) {
		let processor = this.logProcessors.get(executionId);
		if (!processor) {
			processor = createLogProcessor({
				maxEntries: config.logEntriesMaxCount,
				telemetryMaxCount: config.telemetryMaxCount,
				rawMaxCount: config.rawMaxCount,
				rawMaxBytes: config.rawMaxBytes,
			});
			this.logProcessors.set(executionId, processor);
		}
		return processor;
	}

	ingestLogEvents({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		seq,
		events,
	}) {
		this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (
			!Number.isInteger(seq) ||
			seq < 0 ||
			!Array.isArray(events) ||
			events.length === 0 ||
			events.length > 200
		) {
			const err = new Error(
				"log-events requires an integer seq and 1–200 events.",
			);
			err.statusCode = 400;
			err.code = "INVALID_LOG_EVENTS_ARGS";
			throw err;
		}
		const next = this.logEventNextSeq.get(executionId) ?? 0;
		if (seq < next) {
			this.counters.logEventDuplicates += 1;
			return { accepted: true, duplicate: true, seq };
		}
		// JSON-safe clone per event: functions and undefined die here so a
		// hostile or hand-built runner payload can never poison the stored
		// task (which serializes to markdown) with unserializable values.
		// This runs BEFORE any task mutation: an invalid batch must be
		// rejected without writing a spurious gap marker, and the seq
		// cursor stays put so a corrected retry of the same seq is not
		// mistaken for a gap.
		const clean = [];
		for (const event of events) {
			if (!event || typeof event !== "object") continue;
			try {
				const roundTripped = JSON.parse(JSON.stringify(event));
				if (
					roundTripped &&
					typeof roundTripped === "object" &&
					typeof roundTripped.type === "string"
				) {
					clean.push(roundTripped);
				}
			} catch {
				this.counters.logEventsDropped += 1;
			}
		}
		if (clean.length === 0) {
			const err = new Error("log-events carries no usable typed events.");
			err.statusCode = 400;
			err.code = "INVALID_LOG_EVENTS_ARGS";
			throw err;
		}
		const task = taskStore.getTask(projectId, taskId);
		this.counters.logEventBatches += 1;
		if (seq > next) {
			this.counters.logEventGaps += 1;
			_appendProcessLog(
				task,
				`[runner ${runnerId}] event frames truncated — Runner disconnected (frames ${next}–${seq - 1} missing)`,
				{ runnerId },
			);
		}
		// The processor redacts every record (text + structured payloads) at
		// creation, so secrets never reach task.logEntries from this path.
		const processor = this.processorFor(executionId);
		const appended = [];
		for (const event of clean) {
			try {
				appended.push(...processor.handleEvent(event));
			} catch {
				this.counters.logEventsDropped += 1;
			}
		}
		// Stamp runner identity for stored/live dedupe (the frontend drops a
		// live entry once the same executionId:seq lands in a refetch) and
		// for the per-runner log filter. Ids stay processor-assigned —
		// identical to the embedded path's per-stage streamers.
		for (const entry of appended) {
			if (entry && typeof entry === "object") {
				entry.meta = {
					...(entry.meta || {}),
					source: "runner-structured",
					runnerId,
					executionId,
					seq,
				};
			}
		}
		_appendLogEntries(task, appended);
		this.logEventNextSeq.set(executionId, seq + 1);
		return {
			accepted: true,
			duplicate: false,
			seq,
			entryCount: appended.length,
		};
	}

	async completeExecution({
		claimStore,
		taskStore,
		projectStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		sha = null,
		branch = null,
		posture = null,
	}) {
		let outcome;
		try {
			outcome = claimStore.complete(taskId, executionId, epoch);
		} catch (err) {
			this.counters.staleRejected += 1;
			throw err;
		}
		if (outcome.duplicate) {
			this.counters.completionDuplicates += 1;
			return { accepted: true, duplicate: true };
		}
		this.counters.completions += 1;
		const task = taskStore.getTask(projectId, taskId);
		const project = projectStore?.getProject?.(projectId);

		let shaState = "absent";
		if (sha && project?.cwd && !project?.hasUpstreamRepo) {
			try {
				// cat-file -e verifies the object exists; rev-parse alone
				// would echo back any 40-hex string without checking.
				await git(project.cwd, ["cat-file", "-e", `${sha}^{commit}`]);
				shaState = "present";
			} catch {
				shaState = "unverifiable";
				this.counters.unverifiedSha += 1;
			}
		} else if (sha) {
			shaState = "unverified-remote";
			this.counters.unverifiedSha += 1;
			// Deferred verification (Step 3): the backend cannot fetch the
			// remote (D2), so the reported SHA stays pending until a Runner
			// with a fresh fetch confirms it via noteRemoteVerification
			// (POST /tasks/:id/verify-sha). Visible per task, not just as a
			// monitor counter.
			if (task && branch) {
				task.pendingPushVerification = {
					sha,
					branch,
					verified: false,
					reportedAt: new Date().toISOString(),
					reportedBy: runnerId,
				};
			}
		}

		const reportedStage = this.lastStage.get(executionId) ?? null;
		const currentStage = task?.currentStageId ?? null;
		const terminal = ["complete", "failed"].includes(
			String(task?.status).toLowerCase(),
		);
		if ((reportedStage && currentStage && reportedStage !== currentStage) || terminal) {
			this.counters.divergences += 1;
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: `Reconciler: execution ${executionId} reported stage ${reportedStage ?? "?"} but task is at stage ${currentStage ?? "?"} (status ${task?.status}) — report kept, divergence counted.`,
			});
		}

		// Old Runners report `tiers:harness:default` on every stage
		// (the regression this task fixes). Clean the wire value here,
		// the last place before storage, so a mixed-version rollout
		// never writes the fake model segment into the task history.
		const cleanedPosture = cleanReportedPosture(posture);
		const postureBits = [
			runnerId && `runner ${runnerId}`,
			`epoch ${epoch}`,
			sha && `sha ${sha} (${shaState})`,
			branch && `branch ${branch}`,
			cleanedPosture && `posture ${cleanedPosture}`,
		]
			.filter(Boolean)
			.join(", ");
		task?.history?.push({
			timestamp: new Date().toISOString(),
			action: `Runner completed execution ${executionId} (${postureBits}). Lease released.`,
		});
		// G7: a finished stage breaks the death loop — the next stage (or
		// a later retry of this one after real progress) counts from zero.
		if (task) {
			delete task.runnerInterruptCount;
			delete task.runnerInterruptStage;
		}
		this.lastStage.delete(executionId);
		this.logNextSeq.delete(executionId);
		this.logEventNextSeq.delete(executionId);
		this.logProcessors.delete(executionId);
		this.stagePrompt.delete(executionId);
		this.stageServing.delete(executionId);
		return { accepted: true, duplicate: false, shaState, reportedStage };
	}

	/***
	 * MARK: noteRemoteVerification
	 * @description Confirms (or refutes) a previously reported push SHA
	 *   against a Runner's fresh fetch of the remote (Step 3 deferred
	 *   verification). Fenced by the task-claim lease exactly like progress
	 *   and logs: a stale execution's confirmation is rejected, never
	 *   recorded. Sets `task.pendingPushVerification.verified` and counts
	 *   `verifiedSha`; a refuted SHA leaves `verified: false` with the
	 *   refuting Runner named, so the task visibly needs a re-push.
	 * @example ledger.noteRemoteVerification({ claimStore, taskStore, projectId: 'p', taskId: 't', runnerId: 'r', executionId: 'e', epoch: 1, sha: 'abc', present: true }) => { verified: true }
	 ***/
	noteRemoteVerification({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		sha,
		present,
	}) {
		const hold = this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (hold.runnerId !== runnerId) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "lease belongs to another Runner");
		}
		if (!sha || typeof sha !== "string") {
			const err = new Error("verify-sha requires a sha.");
			err.statusCode = 400;
			err.code = "INVALID_VERIFY_ARGS";
			throw err;
		}
		const task = taskStore.getTask(projectId, taskId);
		const verified = present !== false;
		if (task) {
			task.pendingPushVerification = {
				...(task.pendingPushVerification || {}),
				sha,
				verified,
				verifiedAt: new Date().toISOString(),
				verifiedBy: runnerId,
			};
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: verified
					? `Runner ${runnerId} verified push SHA ${sha.slice(0, 7)} against the remote.`
					: `Runner ${runnerId} could NOT find push SHA ${sha.slice(0, 7)} on the remote — task needs a re-push.`,
			});
		}
		if (verified) this.counters.verifiedSha += 1;
		else this.counters.unverifiedSha += 1;
		return { verified };
	}

	interruptExecution({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId = null,
		reason = null,
	}) {
		const hold = claimStore.describe(taskId);
		if (
			hold &&
			executionId &&
			(executionId !== hold.executionId || runnerId !== hold.runnerId)
		) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "not the lease holder");
		}
		const task = taskStore.getTask(projectId, taskId);
		if (["complete", "failed"].includes(String(task?.status).toLowerCase())) {
			const err = new Error(`Task ${taskId} is already terminal.`);
			err.statusCode = 409;
			err.code = "NOTHING_TO_INTERRUPT";
			throw err;
		}
		claimStore.invalidate(taskId);
		this.counters.interrupts += 1;
		// G7: consecutive interrupts per task+stage. A stage change (or a
		// successful completion, which clears both fields) restarts the
		// count — only a Runner dying repeatedly on the SAME stage trips
		// the bound.
		const stageId = task?.currentStageId ?? null;
		const prevStage = task?.runnerInterruptStage ?? null;
		const prevCount = Number.isInteger(task?.runnerInterruptCount) ? task.runnerInterruptCount : 0;
		const interruptCount = prevStage === stageId ? prevCount + 1 : 1;
		const escalated = interruptCount >= MAX_RUNNER_INTERRUPTS;
		if (task) {
			task.runnerInterruptStage = stageId;
			task.runnerInterruptCount = interruptCount;
			task.status = "interrupted";
			const cleanReason =
				typeof reason === "string" && reason.trim() ? reason.trim().slice(0, 500) : "";
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: `Runner ${runnerId} interrupted execution ${executionId ?? hold?.executionId ?? "?"} — lease dropped, re-queues as interrupted.${cleanReason ? ` Reason: ${cleanReason}` : ""}`,
			});
			if (escalated) {
				this.counters.interruptEscalations += 1;
				task?.history?.push({
					timestamp: new Date().toISOString(),
					action: `Runner deaths escalated: ${interruptCount} consecutive interrupts on stage ${stageId ?? "?"} (bound ${MAX_RUNNER_INTERRUPTS}) — needs operator attention, auto re-queue continues.`,
				});
			}
		}
		for (const id of [hold?.executionId, executionId]) {
			if (id) {
				this.lastStage.delete(id);
				this.logNextSeq.delete(id);
				this.logEventNextSeq.delete(id);
				this.logProcessors.delete(id);
				this.stagePrompt.delete(id);
				this.stageServing.delete(id);
			}
		}
		return { interrupted: true, interruptCount, escalated };
	}

	/***
	 * MARK: stageFor
	 * @description Current stage reported by a live execution (progress
	 *   `started`/`finished` events). Null when unknown or finished —
	 *   per-runner monitor widgets join this to the claim hold.
	 * @example ledger.stageFor('exec-1') => 'stage-a'
	 * @param {string} executionId - Lease execution id.
	 * @returns {string|null} Last reported stage id.
	 ***/
	stageFor(executionId) {
		return this.lastStage.get(executionId) ?? null;
	}

	/***
	 * MARK: promptFor
	 * @description Exact stage prompt a live execution reported at start
	 *   (`prompted` progress event). Null when unreported or finished —
	 *   per-runner monitor widgets render the with-prompt card from this.
	 * @example ledger.promptFor('exec-1') => '# Task\n...'
	 * @param {string} executionId - Lease execution id.
	 * @returns {string|null} Reported stage prompt.
	 ***/
	promptFor(executionId) {
		return this.stagePrompt.get(executionId) ?? null;
	}

	/***
	 * MARK: servingFor
	 * @description Serving harness/model a live execution reported at start
	 *   (`prompted` progress event). Null when unreported or finished —
	 *   per-runner monitor widgets show these pills instead of the fleet
	 *   advertised capabilities.
	 * @example ledger.servingFor('exec-1') => { harness: 'pi', model: 'x' }
	 * @param {string} executionId - Lease execution id.
	 * @returns {Object|null} Serving `{ harness, model }`.
	 ***/
	servingFor(executionId) {
		return this.stageServing.get(executionId) ?? null;
	}

	snapshot() {
		return { ...this.counters };
	}
}

import { generateStageReportContent } from "../../watch/index.js";
import { redactSecretsText } from "../../../shared/redactSecrets.js";
import { recordReliabilitySample } from "../../watch/reliabilityShared.js";
import { stageWantsReport } from "../../promptCuration.js";
import { stageElapsedSeconds } from "../stagePolicy.js";
import { resolveStagesForTask } from "../stageResolution.js";
import { normalizeStageType } from "../../projectStore.js";
import { ALIAS_HARNESS_ID } from "../../../shared/modelAliases.js";
import { routeStageError } from "./routeStageError.js";
import { parkTaskForSurvey } from "./parkTaskForSurvey.js";

/***
 * MARK: applyRunnerReport
 * @description Engine-owned finish for a Runner-reported stage (remote
 *   dispatch integration, ADR 0009 step 6). The Runner owns git
 *   (clone/worktree/commit/push — transport row 1/2, D2: the backend never
 *   touches remotes for Runner work); the backend owns everything else,
 *   composing the SAME standalone transitions as the embedded path:
 *   formal report save (opt-in stages), reliability sample, question-me
 *   survey park (shared with executeStage — a remote run can never skip
 *   the human survey), failure routing via routeStageError, and
 *   advanceStage plus the scheduler follow-on kick. Call only after the
 *   lease fence accepted the execution (complete-execution does that).
 * @example await applyRunnerReport({ store, projectStore, projectId: 'p', taskId: 't', outcome: { status: 'passed', output: '...' } }) => { advanced: true, ... }
 * @param {Object} args - Context.
 * @param {Object} args.store - Task store.
 * @param {Object} args.projectStore - Project store.
 * @param {string} args.projectId - Project id.
 * @param {string} args.taskId - Task id.
 * @param {Object} args.outcome - Runner outcome.
 * @param {string} args.outcome.status - `passed` or `failed`.
 * @param {string} [args.outcome.output] - Final assistant text.
 * @param {string} [args.outcome.summary] - Run summary.
 * @param {Array} [args.outcome.modifiedFiles] - Modified files.
 * @param {string} [args.outcome.harnessId] - Harness that ran.
 * @param {string|null} [args.outcome.modelRef] - Served model the Runner
 *   reported (already normalized: null for CI/merge/harness-managed).
 *   Falls back to the dispatch-time `currentRunAttribution`, then to the
 *   stage slot, so the persisted report names the model that actually ran.
 * @param {string} [args.outcome.failureKind] - Failure taxonomy kind.
 * @param {string} [args.outcome.failureReason] - Failure message.
 * @param {string} [args.outcome.duration] - Run duration seconds.
 * @param {string} [args.outcome.runnerId] - Reporting Runner.
 * @returns {Promise<Object>} `{ advanced, status, ... }`.
 ***/
export async function applyRunnerReport({
	store,
	projectStore,
	projectId,
	taskId,
	outcome,
}) {
	const task = store.getTask(projectId, taskId);
	if (!task) {
		const err = new Error(`Task ${taskId} not found`);
		err.statusCode = 404;
		err.code = "TASK_NOT_FOUND";
		throw err;
	}
	const project = projectStore?.getProject?.(projectId);
	// The runner's completion payload (final assistant text, summaries) is
	// committed to the repository via stage reports and task markdown — the
	// same guarantee as the live log path: redact before persistence.
	// Structured log entries ingested live are already redacted at creation.
	const redactedOutput = redactSecretsText(outcome.output || "");
	const redactedSummary = redactSecretsText(outcome.summary || "");
	const stages = resolveStagesForTask(project, task);
	const stage =
		stages.find(
			(s) =>
				String(s.id) === String(task.currentStageId) ||
				(s.name &&
					String(s.name).toLowerCase() ===
						String(task.currentStageId).toLowerCase()),
		) ||
		stages[0] || { id: "stage", name: "Stage", type: "agent" };
	const stageType = normalizeStageType(stage.type);
	const bridge = store.eventBridge;
	const cwd = project?.cwd;
	const via = outcome.runnerId ? `via Runner ${outcome.runnerId}` : "via Runner";
	const duration = outcome.duration || "0.0";
	// The served model for the persisted report: the Runner's explicit report
	// wins, then the dispatch-time stamp (what the Runner was matched on),
	// then the stage slot. Blank/"default" values are absent, never worded —
	// scripted stages record no model at all.
	const dispatchAttribution =
		task.currentRunAttribution &&
		String(task.currentRunAttribution.stageId) === String(task.currentStageId)
			? task.currentRunAttribution
			: null;
	const cleanRef = (value) =>
		typeof value === "string" && value.trim() && value.trim().toLowerCase() !== "default"
			? value.trim()
			: null;
	// The stage slot is a last-resort fallback only: on an alias-harness
	// stage `stage.model` is the ALIAS NAME, not a model, so it must never be
	// recorded as the run's modelRef.
	const stageHarnessIsAlias =
		String(stage.harness ?? project?.harness ?? "") === ALIAS_HARNESS_ID;
	const reportModelRef =
		cleanRef(outcome.modelRef) ??
		cleanRef(dispatchAttribution?.modelRef) ??
		(stageHarnessIsAlias ? null : cleanRef(stage.model));
	const reportAliasName = cleanRef(dispatchAttribution?.aliasName);
	const reportTargetIndex = Number.isInteger(dispatchAttribution?.targetIndex)
		? dispatchAttribution.targetIndex
		: null;

	if (outcome.status === "failed") {
		const err = new Error(outcome.failureReason || "Stage failed on the Runner");
		// The runner's completion payload carries the tail of the run output
		// (runner/daemon.js caps it). Keep it on the error so the failure
		// report renders the actual failing output instead of only the
		// reason — thin "exit code 1" reports hid every branch result
		// (task b5716327). handleStageFailure already renders error.stdout
		// into the report, lastError, and timeline excerpt.
		if (redactedOutput) err.stdout = redactedOutput;
		return routeStageError(
			store,
			projectId,
			taskId,
			stage,
			err,
			{
				stages,
				bridge,
				projectCwd: cwd,
				runOutcome: {
					harnessId: outcome.harnessId,
					// The served model/alias names the failed run on its
					// timeline row too (blank for scripted stages).
					modelRef: reportModelRef,
					aliasName: reportAliasName,
					targetIndex: reportTargetIndex,
					failureKind: outcome.failureKind,
				},
				classifyAs: {
					failureKind: outcome.failureKind,
					failureReason: outcome.failureReason,
				},
			},
		);
	}

	const at = Date.now();
	recordReliabilitySample(store, projectId, taskId, {
		harnessId: outcome.harnessId || "unknown",
		failureKind: "none",
		at,
		atRaw: new Date(at).toISOString(),
		stageId: stage.id,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[SYSTEM] Stage '${stage.name || stage.id}' completed in ${duration}s (${via})`,
		{ taskId, stageId: stage.id, duration },
	);

	if (stageWantsReport(stage)) {
		const reportContent = generateStageReportContent({
			task,
			stage,
			output: redactedOutput,
			summary: redactedSummary,
			modifiedFiles: outcome.modifiedFiles || [],
			status: "PASSED",
			duration,
		});
		store.saveStageReport(projectId, taskId, {
			stageName: stage.name || stage.id,
			stageId: stage.id,
			duration: stageElapsedSeconds(task),
			status: "PASSED",
			content: reportContent,
			projectCwd: cwd,
			harnessId: outcome.harnessId,
			failureKind: outcome.failureKind || "none",
			// The served model/alias the run actually used (Runner-reported,
			// else the dispatch stamp) — absent for scripted stages, so their
			// reports and cards never name a model.
			modelRef: reportModelRef,
			aliasName: reportAliasName,
			targetIndex: reportTargetIndex,
		});
	}

	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Agent stage completed: ${stage.name || stage.id} (${via})`,
	});
	store._saveTaskMarkdown(cwd, task);

	const surveyPark = parkTaskForSurvey({
		store,
		projectId,
		taskId,
		task,
		stage,
		projectObj: project,
		cwd,
		bridge,
		stageType,
		finalOutput: redactedOutput,
		streamedOutput: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		duration,
		via,
	});
	if (surveyPark.parked) return { advanced: false, ...surveyPark.response };

	task.surveyPending = false;
	task.infraRetryCount = 0;
	store.advanceStage(projectId, taskId, stages, bridge, cwd);

	store.lastCompletedTask = { projectId, taskId, timestamp: Date.now() };
	if (store.schedulerRunning) {
		setTimeout(() => {
			store.scheduleTick().catch(() => {});
		}, 50);
	}

	return {
		advanced: true,
		task,
		stageType,
		status: "passed",
		output: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		// The served model that actually ran (Runner-reported > dispatch
		// stamp > stage slot), not just the configured slot.
		model: reportModelRef,
		duration,
	};
}

